<?php
$effectiveTaxBase=max(0,(float)$invoice['subtotal']-(float)$invoice['discount']);
$effectiveTaxRate=$effectiveTaxBase>0?round((float)$invoice['tax']/$effectiveTaxBase*100,2):0;
$canAdjust=!in_array($invoice['status'],['draft','cancelled','refunded'],true);
$remainingAdjustment=max(0,(float)$invoice['total']-(float)$invoice['adjustment_total']);
?>
