<?php if((float)$invoice['adjustment_total']>0): ?><section class="invoice-adjustment-banner <?= $invoice['status']==='cancelled'?'is-cancelled':'is-refunded' ?>"><div><i class="fal fa-<?= $invoice['status']==='cancelled'?'ban':'undo-alt' ?>"></i><span><strong><?= e(ucwords(str_replace('_',' ',$invoice['status']))) ?></strong><small><?= count($invoice['adjustments']) ?> adjustment document<?= count($invoice['adjustments'])===1?'':'s' ?> issued against this invoice</small></span></div><div><small>Original <?= e(money($invoice['total'])) ?></small><strong>Net <?= e(money($invoice['adjusted_total'])) ?></strong></div></section><?php endif; ?>

<div class="invoice-screen-document">@include('agency.invoice-document')</div>

