<?php if(!empty($invoice['payments'])): ?><section class="panel mt-3"><div class="panel-hdr"><h2>Payment history</h2></div><div class="panel-container show"><div class="panel-content"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Date</th><th>Amount</th><th>Method</th><th>Reference</th><th>Recorded by</th></tr></thead><tbody><?php foreach($invoice['payments'] as $payment): ?><tr><td><?= e(date('M j, Y',strtotime($payment['payment_date']))) ?></td><td><strong><?= e(money($payment['amount'])) ?></strong></td><td><?= e($payment['method']) ?></td><td><?= e($payment['reference']?:'—') ?></td><td><?= e($payment['recorded_by_name']?:'System') ?></td></tr><?php endforeach; ?></tbody></table></div></div></div></section><?php endif; ?>

