tion>Cash</option><option>Account credit</option><option>Other</option></select></div></div><div class="col-12"><div class="form-group"><label class="required">Reason / credited item</label><textarea class="form-control" name="reason" rows="3" required placeholder="Describe the overcharge, returned service, or agreed credit"></textarea></div></div><div class="col-12"><div class="form-group mb-0"><label>Reference</label><input class="form-control" name="reference" placeholder="Transaction, approval, or bank reference"></div></div></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-dismiss="modal">Close</button><button class="btn btn-warning" type="submit" data-confirm="Create this partial-refund credit note? The accounting record cannot be deleted."><i class="fal fa-file-minus mr-1"></i>Create credit note</button></div></form></div></div></div>

