on></select></div><div class="form-group mb-0"><label>Reference</label><input class="form-control" name="reference" placeholder="Approval or transaction reference"></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-dismiss="modal">Keep invoice</button><button class="btn btn-danger" type="submit" data-confirm="Cancel this invoice and issue a permanent cancellation certificate?"><i class="fal fa-ban mr-1"></i>Cancel & issue certificate</button></div></form></div></div></div><?php endif; ?>
